fun main() {
    val bs = "héllo €".encodeToByteArray()
    println(bs.contentToString())
    println(bs.decodeToString())
    println(bs.size)
    val c = 'a'
    println(c.code)
    println('7'.digitToInt())
    println('f'.digitToInt(16))
    println('z'.digitToIntOrNull())
    println(3.digitToChar())
    for (ch in 'a'..'e') print(ch)
    println()
    println('a' + 1)
    println('d' - 'a')
    println(('a'..'z').count())
    println('x' in 'a'..'z')
    println(c.uppercaseChar())
    println('Z'.lowercaseChar())
    println(Char(66))
    println(c.isLetter())
    println('5'.isDigit())
    println(' '.isWhitespace())
    println(c.compareTo('b'))
    println(c.hashCode())
    println('é'.code)
    println("abc".map { it.code })
    println(65.toChar())
    println(('a'..'e').toList())
    println(('a'..'e' step 2).toList())
    println(('e' downTo 'a').toList())
    println(Char.MAX_VALUE.code)
    println(c.isUpperCase())
    println(c.toString() + 'b')
}
